import SwiftUIimport Firebasestruct TimelineTaskRow: View {    @EnvironmentObject var session : UserSession    @EnvironmentObject var viewModel : DesignTokensViewModel    var task: TaskItem    var toggle: () -> Void    var body: some View {        HStack(alignment: .top, spacing: 16) {            // Línea del timeline            VStack {                Circle()                    .fill(task.isCompleted ?                          Color(hex: viewModel.config?.colors.tasksColor ?? "#00FF00") :                            Color(hex: "#FF0000"))                    .frame(width: 14, height: 14)                Rectangle()                    .fill(Color(hex: viewModel.config?.colors.cardBackground ?? "#888888").opacity(0.5))                    .frame(width: 3)                    .frame(maxHeight: .infinity)            }            // Tarjeta            VStack(alignment: .leading, spacing: 6) {                HStack {                    Text(task.title)                        .font(.headline)                        .foregroundColor(Color(hex: viewModel.config?.colors.mainFontColor ?? "#FFFFFF"))                    Spacer()                    Button(action: {                        toggleTaskCompletion(task, session: session)                    }) {                        Image(systemName: task.isCompleted ? "checkmark.circle.fill" : "circle")                            .foregroundColor(                                task.isCompleted ?                                Color(hex: viewModel.config?.colors.tasksColor ?? "#00FF00") :                                  Color(hex: "#FF0000")                            )                            .font(.title3)                    }                }                if !task.description.isEmpty {                    Text(task.description)                        .font(.subheadline)                        .foregroundColor(Color(hex: viewModel.config?.colors.mainFontColor ?? "#FFFFFF").opacity(0.8))                        .padding(.top, 2)                }                Text("Entrega: \(task.dueDate.formatted(date: .abbreviated, time: .omitted))")                    .font(.caption)                    .foregroundColor(Color(hex: viewModel.config?.colors.cardFontColor ?? "#CCCCCC"))                    .padding(.top, 4)            }            .padding()            .background(Color(hex: viewModel.config?.colors.cardBackground ?? "#2C2C2E"))            .cornerRadius(16)            .shadow(color: Color(hex: viewModel.config?.colors.mainColor ?? "#FF5733").opacity(0.15),                    radius: 6, x: 0, y: 3)            .animation(.spring(), value: task.isCompleted)        }    }}extension TimelineTaskRow {    func toggleTaskCompletion(_ task: TaskItem, session : UserSession) {        guard let userId = session.currentUser?.id else { return }        let ref = Database.database().reference()            .child("institutions")       // 1. Entra a institutions            .child(viewModel.config?.values.Institucion ?? "shujin")        // 2. Entra a "shujin" (o la que corresponda)            .child("data")               // 3. Entra al nodo "data"            .child("users")              // 4. Entra a "users"            .child(userId)               // 5. ID del usuario            .child("subjects")           // 6. Entra a las materias            .child(task.subjectKey)            // 7. Tienes que especificar la materia (sub1, sub2, etc.)            .child("tasks")              // 8. Entra a la lista de tareas            .child(task.id)              // 9. Finalmente el ID de la tarea        print(ref)        print("llegue a el task compeltion")        let newStatus = !task.isCompleted        ref.updateChildValues(["isCompleted": newStatus]) { error, _ in            if let error = error {                print("Error al actualizar tarea: \(error)")                return            }        }        DispatchQueue.main.async {                        toggle()   // <-- aquí se actualiza la UI local                    }    }}